@namespace sv_df0a64c659a94eff9af3de4be5940d82.Components.Pages.Apply

<div class="step-indicator">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var cssClass = GetStepClass(stepIndex);
        var isClickable = stepIndex < CurrentStep;
        <div class="step-item @cssClass" @onclick="() => OnStepClick(stepIndex, isClickable)" role="button" tabindex="@(isClickable ? 0 : -1)">
            <div class="step-circle">
                @if (stepIndex < CurrentStep)
                {
                    <span>✓</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
            @if (stepIndex < StepNames.Count - 1)
            {
                <div class="step-connector"></div>
            }
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> StepNames =
    [
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    ];

    private string GetStepClass(int step)
    {
        if (step < CurrentStep) return "completed";
        if (step == CurrentStep) return "active";
        return "future";
    }

    private async Task OnStepClick(int step, bool isClickable)
    {
        if (isClickable)
            await OnStepClicked.InvokeAsync(step);
    }
}

.step-indicator {
    display: flex;
    justify-content: center;
    align-items: flex-start;
    gap: 0;
    margin-bottom: 2rem;
    padding: 1.5rem 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    position: relative;
    flex: 1;
    min-width: 0;
}

.step-item.completed {
    cursor: pointer;
}

.step-circle {
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    border: 2px solid #d1d5db;
    background: #fff;
    color: #9ca3af;
    transition: all 0.2s;
    z-index: 1;
}

.step-item.active .step-circle {
    border-color: #3b82f6;
    background: #3b82f6;
    color: #fff;
}

.step-item.completed .step-circle {
    border-color: #10b981;
    background: #10b981;
    color: #fff;
}

.step-item.future .step-circle {
    border-color: #d1d5db;
    background: #f9fafb;
    color: #9ca3af;
}

.step-label {
    margin-top: 0.5rem;
    font-size: 0.8rem;
    color: #6b7280;
    text-align: center;
    white-space: nowrap;
}

.step-item.active .step-label {
    color: #3b82f6;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #10b981;
    font-weight: 500;
}

.step-connector {
    position: absolute;
    top: 1.25rem;
    left: calc(50% + 1.25rem);
    width: calc(100% - 2.5rem);
    height: 2px;
    background: #d1d5db;
}

.step-item.completed .step-connector {
    background: #10b981;
}

@namespace sv_df0a64c659a94eff9af3de4be5940d82.Components.Pages.Apply

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button type="button" class="btn-remove" @onclick="OnRemove">✕ Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" value="@Entry.Company"
                   @onchange="e => UpdateEntry(Entry with { Company = e.Value?.ToString() ?? string.Empty })" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" value="@Entry.Title"
                   @onchange="e => UpdateEntry(Entry with { Title = e.Value?.ToString() ?? string.Empty })" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => UpdateEntry(Entry with { StartDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : Entry.StartDate })" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty)" disabled="@IsCurrent"
                   @onchange="e => UpdateEntry(Entry with { EndDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null })" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="ToggleCurrent" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description"
                  @onchange="e => UpdateEntry(Entry with { Description = e.Value?.ToString() ?? string.Empty })"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null && Entry.StartDate != default;

    private async Task UpdateEntry(WorkEntry updated) => await OnEntryChanged.InvokeAsync(updated);

    private async Task ToggleCurrent(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        await UpdateEntry(Entry with { EndDate = isCurrent ? null : DateTime.Today });
    }
}

@namespace sv_df0a64c659a94eff9af3de4be5940d82.Components.Pages.Apply

<div class="reference-card">
    <div class="reference-header">
        <h4>Reference @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button type="button" class="btn-remove" @onclick="OnRemove">✕ Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Name *</label>
            <input type="text" value="@Reference.Name"
                   @onchange="e => Update(Reference with { Name = e.Value?.ToString() ?? string.Empty })" />
        </div>
        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" value="@Reference.Relationship"
                   @onchange="e => Update(Reference with { Relationship = e.Value?.ToString() ?? string.Empty })" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Reference.Email"
                   @onchange="e => Update(Reference with { Email = e.Value?.ToString() ?? string.Empty })" />
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" value="@Reference.Phone"
                   @onchange="e => Update(Reference with { Phone = e.Value?.ToString() ?? string.Empty })" />
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public Reference Reference { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<Reference> OnReferenceChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private async Task Update(Reference updated) => await OnReferenceChanged.InvokeAsync(updated);
}

