@namespace sv_df0a64c659a94eff9af3de4be5940d82.Components.Pages.Apply

<div class="step-content">
    <h3>Personal Information</h3>

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" value="@Info.FullName"
               @onchange="e => Update(Info with { FullName = e.Value?.ToString() ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Info.Email"
               @onchange="e => Update(Info with { Email = e.Value?.ToString() ?? string.Empty })" />
        @if (!string.IsNullOrEmpty(EmailError))
        {
            <span class="field-error">@EmailError</span>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" value="@Info.Phone"
                   @onchange="e => Update(Info with { Phone = e.Value?.ToString() ?? string.Empty })" />
        </div>
        <div class="form-group">
            <label>Address *</label>
            <input type="text" value="@Info.Address"
                   @onchange="e => Update(Info with { Address = e.Value?.ToString() ?? string.Empty })" />
        </div>
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next →")
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfo Info { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<PersonalInfo> OnInfoChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string? ValidationError;
    private string? EmailError;
    private bool IsValidating;

    private async Task Update(PersonalInfo updated)
    {
        EmailError = null;
        await OnInfoChanged.InvokeAsync(updated);
    }

    private async Task HandleNext()
    {
        ValidationError = null;
        EmailError = null;

        if (string.IsNullOrWhiteSpace(Info.FullName) ||
            string.IsNullOrWhiteSpace(Info.Email) ||
            string.IsNullOrWhiteSpace(Info.Phone) ||
            string.IsNullOrWhiteSpace(Info.Address))
        {
            ValidationError = "Please fill in all required fields.";
            return;
        }

        IsValidating = true;
        try
        {
            var isValid = await ValidateEmail(Info.Email);
            if (!isValid)
            {
                EmailError = "Please enter a valid email address.";
                return;
            }
            await OnNext.InvokeAsync();
        }
        finally
        {
            IsValidating = false;
        }
    }
}

@namespace sv_df0a64c659a94eff9af3de4be5940d82.Components.Pages.Apply

<div class="step-content">
    <h3>Work History</h3>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@Entries[index]"
                       Index="index"
                       CanRemove="@(Entries.Count > 1)"
                       OnEntryChanged="e => UpdateEntry(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-outline" @onclick="OnBack">← Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next →</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntry> Entries { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<List<WorkEntry>> OnEntriesChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    private async Task UpdateEntry(int index, WorkEntry updated)
    {
        var list = new List<WorkEntry>(Entries) { [index] = updated };
        await OnEntriesChanged.InvokeAsync(list);
    }

    private async Task AddEntry()
    {
        var list = new List<WorkEntry>(Entries)
        {
            new(string.Empty, string.Empty, DateTime.Today, DateTime.Today, string.Empty)
        };
        await OnEntriesChanged.InvokeAsync(list);
    }

    private async Task RemoveEntry(int index)
    {
        var list = new List<WorkEntry>(Entries);
        list.RemoveAt(index);
        await OnEntriesChanged.InvokeAsync(list);
    }

    private async Task HandleNext()
    {
        ValidationError = null;
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == default)
            {
                ValidationError = "Please fill in company, title, and start date for all positions.";
                return;
            }
        }
        await OnNext.InvokeAsync();
    }
}

@namespace sv_df0a64c659a94eff9af3de4be5940d82.Components.Pages.Apply

<div class="step-content">
    <h3>References</h3>
    <p class="step-description">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Reference="@References[index]"
                       Index="index"
                       CanRemove="@(References.Count > 1)"
                       OnReferenceChanged="e => UpdateReference(index, e)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-outline" @onclick="OnBack">← Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next →</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<Reference> References { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<List<Reference>> OnReferencesChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    private async Task UpdateReference(int index, Reference updated)
    {
        var list = new List<Reference>(References) { [index] = updated };
        await OnReferencesChanged.InvokeAsync(list);
    }

    private async Task AddReference()
    {
        if (References.Count >= 3) return;
        var list = new List<Reference>(References)
        {
            new(string.Empty, string.Empty, string.Empty, string.Empty)
        };
        await OnReferencesChanged.InvokeAsync(list);
    }

    private async Task RemoveReference(int index)
    {
        var list = new List<Reference>(References);
        list.RemoveAt(index);
        await OnReferencesChanged.InvokeAsync(list);
    }

    private async Task HandleNext()
    {
        ValidationError = null;
        if (References.Count < 2)
        {
            ValidationError = "Please provide at least 2 references.";
            return;
        }
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) || string.IsNullOrWhiteSpace(r.Email))
            {
                ValidationError = "Please fill in name, relationship, and email for all references.";
                return;
            }
        }
        await OnNext.InvokeAsync();
    }
}

@namespace sv_df0a64c659a94eff9af3de4be5940d82.Components.Pages.Apply

<div class="step-content">
    <h3>Cover Letter</h3>

    <div class="form-group">
        <textarea rows="12" maxlength="2000" value="@CoverLetter"
                  @oninput="HandleInput"
                  placeholder="Write your cover letter here..."></textarea>
        <div class="char-count @(CoverLetter.Length >= 2000 ? "at-limit" : "")">
            @CoverLetter.Length / 2000 characters
        </div>
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-outline" @onclick="OnBack">← Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next →</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = string.Empty;
    [Parameter, EditorRequired] public EventCallback<string> OnCoverLetterChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    private async Task HandleInput(ChangeEventArgs e)
    {
        var text = e.Value?.ToString() ?? string.Empty;
        if (text.Length > 2000) text = text[..2000];
        await OnCoverLetterChanged.InvokeAsync(text);
    }

    private async Task HandleNext()
    {
        ValidationError = null;
        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            ValidationError = "Please write a cover letter.";
            return;
        }
        await OnNext.InvokeAsync();
    }
}

@namespace sv_df0a64c659a94eff9af3de4be5940d82.Components.Pages.Apply

<div class="step-content">
    <h3>Review & Submit</h3>

    @if (IsSubmitted)
    {
        <div class="confirmation">
            <div class="confirmation-icon">✓</div>
            <h4>Application Submitted!</h4>
            <p>Your application has been received. Your application ID is:</p>
            <div class="application-id">#@ApplicationId</div>
        </div>
    }
    else
    {
        <div class="review-section">
            <div class="review-header">
                <h4>Personal Information</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </div>

        <div class="review-section">
            <div class="review-header">
                <h4>Work History</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                    <span class="review-dates">
                        @entry.StartDate.ToString("MMM yyyy") –
                        @(entry.EndDate.HasValue ? entry.EndDate.Value.ToString("MMM yyyy") : "Present")
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="review-description">@entry.Description</p>
                    }
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h4>References</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-reference">
                    <strong>@r.Name</strong> — @r.Relationship<br />
                    @r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $" | {r.Phone}" : "")
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h4>Cover Letter</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <p class="review-cover-letter">@CoverLetter</p>
        </div>

        @if (!string.IsNullOrEmpty(SubmitError))
        {
            <div class="validation-error">@SubmitError</div>
        }

        <div class="step-buttons">
            <button type="button" class="btn btn-outline" @onclick="OnBack">← Back</button>
            <button type="button" class="btn btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfo Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntry> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<Reference> References { get; set; } = default!;
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = string.Empty;
    [Parameter, EditorRequired] public EventCallback<int> OnEditSection { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public Func<Task<int>> OnSubmit { get; set; } = default!;

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int ApplicationId;
    private string? SubmitError;

    private async Task HandleSubmit()
    {
        IsSubmitting = true;
        SubmitError = null;
        try
        {
            ApplicationId = await OnSubmit();
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            SubmitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

