@namespace sv_df0a64c659a94eff9af3de4be5940d82.Components.Pages.Apply

<div class="step-content">
    <h3>Cover Letter</h3>

    <div class="form-group">
        <textarea rows="12" maxlength="2000" value="@CoverLetter"
                  @oninput="HandleInput"
                  placeholder="Write your cover letter here..."></textarea>
        <div class="char-count @(CoverLetter.Length >= 2000 ? "at-limit" : "")">
            @CoverLetter.Length / 2000 characters
        </div>
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-outline" @onclick="OnBack">← Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next →</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = string.Empty;
    [Parameter, EditorRequired] public EventCallback<string> OnCoverLetterChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    private async Task HandleInput(ChangeEventArgs e)
    {
        var text = e.Value?.ToString() ?? string.Empty;
        if (text.Length > 2000) text = text[..2000];
        await OnCoverLetterChanged.InvokeAsync(text);
    }

    private async Task HandleNext()
    {
        ValidationError = null;
        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            ValidationError = "Please write a cover letter.";
            return;
        }
        await OnNext.InvokeAsync();
    }
}

