@page "/apply"
@using sv_df0a64c659a94eff9af3de4be5940d82.Components.Pages.Apply
@using sv_df0a64c659a94eff9af3de4be5940d82.Models
@inject IApplicationService AppService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-container">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="@currentStep" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Info="@personalInfo"
                              OnInfoChanged="info => personalInfo = info"
                              OnNext="NextStep"
                              ValidateEmail="AppService.ValidateEmailAsync" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnEntriesChanged="entries => workEntries = entries"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep References="@references"
                            OnReferencesChanged="refs => references = refs"
                            OnNext="NextStep"
                            OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             OnCoverLetterChanged="text => coverLetter = text"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep Personal="@personalInfo"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnEditSection="GoToStep"
                        OnBack="PreviousStep"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep;
    private PersonalInfo personalInfo = new(string.Empty, string.Empty, string.Empty, string.Empty);
    private List<WorkEntry> workEntries = [new(string.Empty, string.Empty, DateTime.Today, DateTime.Today, string.Empty)];
    private List<Reference> references =
    [
        new(string.Empty, string.Empty, string.Empty, string.Empty),
        new(string.Empty, string.Empty, string.Empty, string.Empty)
    ];
    private string coverLetter = string.Empty;

    private void NextStep() => currentStep = Math.Min(currentStep + 1, 4);
    private void PreviousStep() => currentStep = Math.Max(currentStep - 1, 0);
    private void GoToStep(int step) => currentStep = step;

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            personalInfo,
            new WorkHistory(workEntries),
            references,
            coverLetter
        );
        return await AppService.SubmitApplicationAsync(application);
    }
}

.application-container {
    max-width: 800px;
    margin: 0 auto;
