+/* Buttons */
+.step-buttons {
+    display: flex;
+    justify-content: space-between;
+    margin-top: 2rem;
+    padding-top: 1.5rem;
+    border-top: 1px solid #e5e7eb;
+}
+
+.btn {
+    padding: 0.6rem 1.5rem;
+    border-radius: 0.375rem;
+    font-size: 0.95rem;
+    font-weight: 500;
+    cursor: pointer;
+    border: none;
+    transition: all 0.15s;
+}
+
+.btn:disabled {
+    opacity: 0.6;
+    cursor: not-allowed;
+}
+
+.btn-primary {
+    background: #3b82f6;
+    color: #fff;
+    margin-left: auto;
+}
+
+.btn-primary:hover:not(:disabled) {
+    background: #2563eb;
+}
+
+.btn-outline {
+    background: #fff;
+    color: #374151;
+    border: 1px solid #d1d5db;
+}
+
+.btn-outline:hover {
+    background: #f9fafb;
+}
+
+.btn-secondary {
+    background: #f3f4f6;
+    color: #374151;
+    border: 1px solid #d1d5db;
+    margin-bottom: 1rem;
+}
+
+.btn-secondary:hover {
+    background: #e5e7eb;
+}
+
+.btn-submit {
+    padding: 0.75rem 2rem;
+    font-size: 1rem;
+}
+
+.btn-link {
+    background: none;
+    border: none;
+    color: #3b82f6;
+    cursor: pointer;
+    font-size: 0.9rem;
+    padding: 0;
+    text-decoration: underline;
+}
+
+.btn-link:hover {
+    color: #2563eb;
+}
+
+.btn-remove {
+    background: none;
+    border: none;
+    color: #ef4444;
+    cursor: pointer;
+    font-size: 0.85rem;
+    padding: 0.25rem 0.5rem;
+}
+
+.btn-remove:hover {
+    color: #dc2626;
+    text-decoration: underline;
+}
+
+/* Cards for entries */
+.work-entry-card,
+.reference-card {
+    border: 1px solid #e5e7eb;
+    border-radius: 0.5rem;
+    padding: 1.5rem;
+    margin-bottom: 1rem;
+    background: #f9fafb;
+}
+
+.work-entry-header,
+.reference-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 1rem;
+}
+
+.work-entry-header h4,
+.reference-header h4 {
+    margin: 0;
+    color: #374151;
+}
+
+/* Character count */
+.char-count {
+    text-align: right;
+    font-size: 0.85rem;
+    color: #6b7280;
+    margin-top: 0.25rem;
+}
+
+.char-count.at-limit {
+    color: #ef4444;
+    font-weight: 500;
+}
+
+/* Review section */
+.review-section {
+    border: 1px solid #e5e7eb;
+    border-radius: 0.5rem;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+    background: #f9fafb;
+}
+
+.review-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+.review-header h4 {
+    margin: 0;
+    color: #1f2937;
+}
+
+.review-section dl {
+    display: grid;
+    grid-template-columns: 8rem 1fr;
+    gap: 0.25rem 1rem;
+    margin: 0;
+}
+
+.review-section dt {
+    font-weight: 500;
+    color: #6b7280;
+}
+
+.review-section dd {
+    margin: 0;
+    color: #1f2937;
+}
+
+.review-work-entry {
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #e5e7eb;
+}
+
+.review-work-entry:last-child {
+    border-bottom: none;
+}
+
+.review-dates {
+    font-size: 0.85rem;
+    color: #6b7280;
+}
+
+.review-description {
+    margin: 0.25rem 0 0;
+    color: #4b5563;
+    font-size: 0.9rem;
+}
+
+.review-reference {
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #e5e7eb;
+}
+
+.review-reference:last-child {
+    border-bottom: none;
+}
+
+.review-cover-letter {
+    white-space: pre-wrap;
+    color: #374151;
+    margin: 0;
+}
+
+/* Confirmation */
+.confirmation {
+    text-align: center;
+    padding: 3rem 1rem;
+}
+
+.confirmation-icon {
+    width: 4rem;
+    height: 4rem;
+    background: #10b981;
+    color: white;
+    border-radius: 50%;
+    display: inline-flex;
+    align-items: center;
+    justify-content: center;
+    font-size: 2rem;
+    margin-bottom: 1rem;
+}
+
+.confirmation h4 {
+    font-size: 1.5rem;
+    color: #1f2937;
+    margin-bottom: 0.5rem;
+}
+
+.application-id {
+    font-size: 1.75rem;
+    font-weight: 700;
+    color: #3b82f6;
+    margin-top: 0.5rem;
+}
+

